package com.tiviloom.mobile;
import java.io.*;import java.text.*;import java.util.*;import javax.xml.parsers.*;import org.xml.sax.*;import org.xml.sax.helpers.DefaultHandler;import org.json.*;
final class EpgParser {
 static JSONObject parse(InputStream input,int max)throws Exception{final long deadline=System.currentTimeMillis()+120000;try(InputStream bounded=new FilterInputStream(input){int count,matched;final String pattern="<!DOCTYPE";void scan(int b)throws IOException{char c=Character.toUpperCase((char)(b&255));if(c==pattern.charAt(matched)){if(++matched==pattern.length())throw new IOException("XML DOCTYPE forbidden");}else matched=c=='<'?1:0;}void check(int n)throws IOException{if(n>0)count+=n;if(count>max)throw new IOException("EPG exceeds 150 MiB");if(System.currentTimeMillis()>deadline)throw new java.net.SocketTimeoutException();}@Override public int read()throws IOException{int n=in.read();check(n<0?0:1);if(n>=0)scan(n);return n;}@Override public int read(byte[]b,int off,int len)throws IOException{int n=in.read(b,off,len);check(n);for(int i=0;i<n;i++)scan(b[off+i]);return n;}}){SAXParserFactory f=SAXParserFactory.newInstance();for(String key:Arrays.asList("http://apache.org/xml/features/disallow-doctype-decl","http://xml.org/sax/features/external-general-entities","http://xml.org/sax/features/external-parameter-entities"))try{f.setFeature(key,key.contains("disallow-doctype"));}catch(ParserConfigurationException|SAXException unsupported){}Handler h=new Handler();f.newSAXParser().parse(bounded,h);return new JSONObject().put("programs",h.programs).put("names",h.names);}}
 static long time(String s){try{String[]parts=s.trim().split("\\s+");String d=parts[0],z=parts.length>1?parts[1]:"+0000";if(z.equals("Z"))z="+0000";if(d.length()==12)d+="00";SimpleDateFormat f=new SimpleDateFormat("yyyyMMddHHmmss Z",Locale.US);f.setLenient(false);return f.parse(d+" "+z).getTime();}catch(Exception e){return 0;}}
 static class Handler extends DefaultHandler{JSONArray programs=new JSONArray();JSONObject names=new JSONObject(),p;String channel="",field="";StringBuilder text=new StringBuilder();long now=System.currentTimeMillis();public InputSource resolveEntity(String a,String b)throws SAXException{throw new SAXException("External entities forbidden");}public void startElement(String uri,String local,String name,Attributes a){if(name.equals("channel"))channel=a.getValue("id");if(name.equals("programme")){p=null;try{long start=time(a.getValue("start")),end=time(a.getValue("stop"));if(end>start&&end>now-21600000L&&start<now+604800000L&&programs.length()<45000)p=new JSONObject().put("channel",a.getValue("channel")).put("start",start).put("end",end);}catch(Exception ignored){}}if(Arrays.asList("display-name","title","desc","category").contains(name)){field=name;text.setLength(0);}}public void characters(char[]b,int a,int n){if(!field.isEmpty()&&text.length()<4096)text.append(b,a,Math.min(n,4096-text.length()));}public void endElement(String uri,String local,String name)throws SAXException{try{if(name.equals(field)){String value=text.toString().trim();if(name.equals("display-name")&&channel!=null&&names.length()<30000)names.put(channel,value);else if(p!=null){String key=name.equals("desc")?"description":name;int max=key.equals("description")?180:key.equals("title")?130:60;p.put(key,value.substring(0,Math.min(value.length(),max)));}field="";}if(name.equals("programme")){if(p!=null){if(!p.has("title"))p.put("title","Programme");programs.put(p);}p=null;}if(name.equals("channel"))channel="";}catch(JSONException e){throw new SAXException(e);}}}
}
